// Development only. Facts are generated by Rust from the provenance-tagged fixed inputs.
import template from '../../../tests/fixtures/review/normalized.json';
import raw from '../../../tests/fixtures/review/sgp.json';
import type {
  AnalysisInput,
  CommandMap,
  MatchSummary,
  ReviewReport,
  ReviewNote,
  ReviewFeedback,
  TrainingGoal,
  GoalEvaluation,
  ConnectionState,
  Task,
} from '../../generated/contracts';
import type { CommandName } from './index';
const fixed: { input: AnalysisInput; report: ReviewReport } = JSON.parse(JSON.stringify(template));
let inputs = new Map<string, AnalysisInput>();
let reports = new Map<string, ReviewReport>();
let notes: ReviewNote[] = [];
let feedback: ReviewFeedback[] = [];
let goals: TrainingGoal[] = [];
let evaluations: GoalEvaluation[] = [];
export function resetReviewFixture() {
  inputs = new Map();
  reports = new Map();
  notes = [];
  feedback = [];
  goals = [];
  evaluations = [];
}
export function reviewFixture(
  command: CommandName,
  args: unknown,
  context: {
    matches: MatchSummary[];
    connection: ConnectionState;
    now: Date;
    task: (reference: string, kind: Task['kind']) => Task;
    emit: (kind: string) => void;
    fail: (code: string) => never;
  },
): unknown {
  const { matches, connection, now, task, emit, fail } = context;
  const ref = args as CommandMap['get_match_review_data']['input'];
  const k = `${ref.playerKey}|${ref.matchKey}`;
  const m = matches.find((m) => m.matchKey === ref.matchKey && m.playerKey === ref.playerKey);
  const findReport = (id: string) => reports.get(id) || fail('not_found');
  const input = () => inputs.get(k) || fail('data_incomplete');
  switch (command) {
    case 'get_match_review_data': {
      if (!m) return fail('not_found');
      const report = ref.reportId
        ? findReport(ref.reportId)
        : [...reports.values()].find(
            (r) => r.matchKey === m.matchKey && r.playerKey === m.playerKey,
          ) || null;
      if (report && (report.matchKey !== m.matchKey || report.playerKey !== m.playerKey))
        return fail('invalid_input');
      const i = inputs.get(k);
      return {
        summary: m,
        input: i ? { ...i, frames: [], events: [] } : null,
        report,
        summaryStatus: i ? 'ready' : 'partial',
        timelineStatus: i ? 'ready' : 'missing',
        retryAt: null,
        lastError: null,
        activeTask: null,
        newerInput: false,
        latestInputRevision: i?.revision || null,
      };
    }
    case 'fetch_match_details': {
      if (!m) return fail('not_found');
      if (connection.player?.playerKey !== m.playerKey || connection.phase !== 'connected')
        return fail('forbidden');
      if (!inputs.has(k)) {
        const i = structuredClone(fixed.input);
        i.id = crypto.randomUUID();
        i.fingerprint = i.id;
        i.context.matchKey = m.matchKey;
        i.context.playerKey = m.playerKey;
        i.context.startedAt = m.startedAt;
        i.context.queueId = m.queueId;
        i.context.participants[2].championId = m.championId;
        m.duration = 1800;
        m.kills = 8;
        m.deaths = 2;
        m.assists = 4;
        m.cs = 180;
        inputs.set(k, i);
      }
      emit('review-data-changed');
      return task(input().id, 'fetch_details');
    }
    case 'generate_review': {
      const i = input();
      if (![420, 440].includes(i.context.queueId || 0)) return fail('analysis_unsupported');
      let r = [...reports.values()].find(
        (r) => r.matchKey === ref.matchKey && r.playerKey === ref.playerKey,
      );
      if (!r) {
        r = structuredClone(fixed.report);
        r.id = crypto.randomUUID();
        r.matchKey = ref.matchKey;
        r.playerKey = ref.playerKey;
        r.inputFingerprint = i.fingerprint;
        r.generatedAt = now.toISOString();
        reports.set(r.id, r);
      }
      if (m) m.reviewState = 'ready';
      emit('review-changed');
      return task(r.id, 'generate_review');
    }
    case 'get_review':
      return findReport((args as { id: string }).id);
    case 'get_timeline_slice': {
      const q = args as CommandMap['get_timeline_slice']['input'];
      const i = input();
      const events = i.events.filter(
        (e) =>
          e.timestampMs >= q.fromMs &&
          e.timestampMs <= q.toMs &&
          (!q.kinds.length || q.kinds.includes(e.kind)),
      );
      const cursor = q.cursor || 0;
      const limit = q.limit || 100;
      return {
        events: events.slice(cursor, cursor + limit),
        nextCursor: cursor + limit < events.length ? cursor + limit : null,
        capabilities: i.capabilities,
      };
    }
    case 'get_match_metrics': {
      const q = args as CommandMap['get_match_metrics']['input'];
      const i = input();
      return {
        points: i.frames
          .filter(
            (f) => f.participantId === 3 && f.timestampMs >= q.fromMs && f.timestampMs <= q.toMs,
          )
          .slice(0, q.maxPoints)
          .map((f) => {
            const opponent = i.frames.find(
              (o) => o.timestampMs === f.timestampMs && o.participantId === 8,
            );
            return {
              timestampMs: f.timestampMs,
              gold: f.gold,
              cs: f.cs,
              opponentGold: opponent?.gold ?? null,
              opponentCs: opponent?.cs ?? null,
            };
          }),
        limitations: i.limitations,
      };
    }
    case 'get_review_evidence': {
      const q = args as CommandMap['get_review_evidence']['input'];
      const r = findReport(q.reportId);
      const i = inputs.get(`${r.playerKey}|${r.matchKey}`)!;
      const e = r.evidence.find((e) => e.id === q.evidenceId);
      if (!e) return fail('evidence_unavailable');
      const source: unknown = e.snapshotId === i.summarySnapshot ? raw.summary : raw.timeline;
      let value = source;
      for (const part of e.path.split('/').filter(Boolean))
        value = (value as Record<string, unknown>)[part];
      return { reference: e, raw: value };
    }
    case 'get_review_annotations': {
      const q = args as CommandMap['get_review_annotations']['input'];
      return {
        notes: notes.filter(
          (n) =>
            n.matchKey === q.matchKey &&
            n.playerKey === q.playerKey &&
            (!n.reportId || n.reportId === q.reportId),
        ),
        feedback: feedback.filter((f) => f.reportId === q.reportId),
      };
    }
    case 'save_review_note': {
      const q = args as CommandMap['save_review_note']['input'];
      const old = notes.find((n) => n.id === q.id);
      if ((old?.revision || 0) !== q.expectedRevision) return fail('revision_conflict');
      if (!q.text.trim() || q.text.length > 10000) return fail('invalid_input');
      const n: ReviewNote = {
        id: q.id || crypto.randomUUID(),
        matchKey: q.matchKey,
        playerKey: q.playerKey,
        reportId: q.reportId,
        evidenceId: q.evidenceId,
        text: q.text,
        revision: q.expectedRevision + 1,
        updatedAt: now.toISOString(),
      };
      notes = [...notes.filter((x) => x.id !== n.id), n];
      emit('annotations-changed');
      return n;
    }
    case 'delete_review_note': {
      const q = args as CommandMap['delete_review_note']['input'];
      const n = notes.find((n) => n.id === q.id);
      if (!n) return fail('not_found');
      if (n.revision !== q.expectedRevision) return fail('revision_conflict');
      notes = notes.filter((n) => n.id !== q.id);
      emit('annotations-changed');
      return {};
    }
    case 'save_review_feedback': {
      const q = args as CommandMap['save_review_feedback']['input'];
      const old = feedback.find((f) => f.reportId === q.reportId && f.findingId === q.findingId);
      if ((old?.revision || 0) !== q.expectedRevision) return fail('revision_conflict');
      const f: ReviewFeedback = {
        ...q,
        revision: q.expectedRevision + 1,
        updatedAt: now.toISOString(),
      };
      feedback = [
        ...feedback.filter((f) => f.reportId !== q.reportId || f.findingId !== q.findingId),
        f,
      ];
      emit('annotations-changed');
      return f;
    }
    case 'save_training_goal': {
      const q = args as CommandMap['save_training_goal']['input'];
      const old = goals.find((g) => g.id === q.id);
      if ((old?.revision || 0) !== q.expectedRevision) return fail('revision_conflict');
      const g: TrainingGoal = {
        id: q.id || crypto.randomUUID(),
        scope: q.scope,
        revision: q.expectedRevision + 1,
        version: old?.version || 1,
        state: old ? q.state : 'draft',
        baseline: old?.baseline || [],
        baselineExcluded: old?.baselineExcluded || {},
        createdAt: old?.createdAt || now.toISOString(),
        windowStart: now.toISOString(),
        previousGoalId: null,
      };
      goals = [...goals.filter((g) => g.id !== q.id), g];
      emit('goals-changed');
      return g;
    }
    case 'list_training_goals': {
      const q = args as CommandMap['list_training_goals']['input'];
      const rows = goals.filter(
        (g) => g.scope.playerKey === q.playerKey && (!q.state || g.state === q.state),
      );
      const cursor = q.cursor || 0;
      const limit = q.limit || 50;
      return {
        items: rows.slice(cursor, cursor + limit),
        nextCursor: cursor + limit < rows.length ? cursor + limit : null,
      };
    }
    case 'get_goal_progress': {
      const q = args as CommandMap['get_goal_progress']['input'];
      const goal = goals.find((g) => g.id === q.goalId) || fail('not_found');
      return {
        goal,
        evaluation:
          evaluations.find(
            (e) => e.goalId === q.goalId && (!q.revision || e.revision === q.revision),
          ) || null,
      };
    }
    case 'evaluate_training_goal': {
      const id = (args as { id: string }).id;
      const g = goals.find((g) => g.id === id) || fail('not_found');
      if (g.state !== 'active') return fail('invalid_input');
      const e: GoalEvaluation = {
        id: crypto.randomUUID(),
        goalId: id,
        revision: 1,
        algorithmVersion: '1',
        baseline: null,
        current: null,
        delta: null,
        target: g.scope.target,
        achieved: null,
        members: [],
        excluded: {},
        windowStart: g.windowStart,
        windowEnd: null,
        generatedAt: now.toISOString(),
      };
      evaluations = [...evaluations, e];
      emit('goals-changed');
      return task(e.id, 'evaluate_goal');
    }
    case 'get_player_progress': {
      const q = args as CommandMap['get_player_progress']['input'];
      const rows = [...reports.values()].filter((r) => r.playerKey === q.playerKey);
      return {
        points: rows.map((r) => {
          const i = inputs.get(`${r.playerKey}|${r.matchKey}`)!;
          return {
            matchKey: r.matchKey,
            reportId: r.id,
            startedAt: i.context.startedAt,
            group: `${i.context.queueId}:MIDDLE:16.20:${r.ruleVersion}`,
            metrics: r.metrics.filter((m) =>
              ['cs_10', 'deaths_per_10', 'cs_per_min'].includes(m.id),
            ),
          };
        }),
        excluded: {
          no_report: matches.filter((m) => m.playerKey === q.playerKey).length - rows.length,
        },
        cachedMatches: matches.filter((m) => m.playerKey === q.playerKey).length,
        from: rows.length
          ? inputs.get(`${rows[0].playerKey}|${rows[0].matchKey}`)!.context.startedAt
          : null,
        to: null,
      };
    }
    default:
      return fail('endpoint_unsupported');
  }
}
